function readLease(){try{return JSON.parse(localStorage.getItem(LEASE_STORE)||'null');}catch{return null;}}
function writeLease(value){try{localStorage.setItem(LEASE_STORE,JSON.stringify(value));return true;}catch{return false;}}
function claimExam(id){const now=Date.now(),current=readLease();if(current?.examId===id&&current.completed)return false;if(current&&!current.completed&&current.owner!==TAB_ID&&current.expiresAt>now)return false;const next={examId:id,owner:TAB_ID,expiresAt:now+LEASE_MS,completed:false};if(!writeLease(next)){memoryLeaseId=id;return true;}memoryLeaseId=null;return readLease()?.owner===TAB_ID;}
function ownsExam(){if(memoryLeaseId===exam?.id)return true;const lease=readLease();return !!exam&&!exam.result&&lease?.examId===exam.id&&lease.owner===TAB_ID&&!lease.completed;}
function renewLease(){if(!exam||exam.result||memoryLeaseId===exam.id)return;const lease=readLease();if(lease?.examId===exam.id&&lease.owner===TAB_ID&&!lease.completed)writeLease({...lease,expiresAt:Date.now()+LEASE_MS});}
function closeLease(id){if(memoryLeaseId===id){memoryLeaseId=null;return;}const lease=readLease();if(lease?.examId===id&&lease.owner===TAB_ID)writeLease({...lease,completed:true,expiresAt:Date.now()+86400000});}
const historyKey=item=>item.id||`legacy:${item.at}:${item.errors}:${item.unanswered}`;
function mergeState(remote,local){
  const rewards=[...new Set([...remote.rewards,...local.rewards])].slice(-10000);
  const merged={...local,...mergeJourneyProfile(remote,local),xp:Math.max(remote.xp,local.xp,rewards.length*15),sessions:Math.max(remote.sessions,local.sessions),rewards,records:{...remote.records,...local.records}};
  for(const [id,record] of Object.entries(remote.records))if((record.last||0)>(local.records[id]?.last||0))merged.records[id]=record;
  const history=new Map(remote.history.map(item=>[historyKey(item),item]));for(const item of local.history)history.set(historyKey(item),item);merged.history=[...history.values()].sort((a,b)=>a.at-b.at).slice(-30);
  const lease=readLease(),localId=local.savedExam?.id,remoteId=remote.savedExam?.id;
  if(lease?.completed&&(localId===lease.examId||remoteId===lease.examId))merged.savedExam=null;
  else if(lease&&!lease.completed&&lease.owner!==TAB_ID)merged.savedExam=remote.savedExam;
  else merged.savedExam=local.savedExam;
  return merged;
}
function save(){try{state=mergeState(restoreState(localStorage.getItem(STORE)),state);localStorage.setItem(STORE,JSON.stringify(state));}catch{if(!storageWarning){storageWarning=true;toast('Din browser kan ikke gemme. Du kan stadig øve i denne session.');}}}
function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').classList.add('visible');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3600);}
function sound(correct=true){if(!state.settings.sound)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.connect(gain);gain.connect(audio.destination);osc.frequency.value=correct?520:260;osc.frequency.exponentialRampToValueAtTime(correct?780:190,audio.currentTime+.1);gain.gain.setValueAtTime(.045,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.14);osc.start();osc.stop(audio.currentTime+.15);}catch{}}
function applySettings(){narrator.stop();document.body.classList.toggle('calm',!state.settings.humor);document.body.classList.toggle('no-motion',!state.settings.motion||reduceMotion.matches);$('humor-toggle').setAttribute('aria-pressed',String(state.settings.humor));$('humor-toggle').querySelector('b').textContent=state.settings.humor?'ON':'OFF';world?.setMotion(state.settings.motion&&!reduceMotion.matches);judgeGame?.setHumor(state.settings.humor);judgeGame?.setMotion(state.settings.motion&&!reduceMotion.matches);}
function makeWorld(canvas,options={}){const q=canvas.id==='question-scene'?(location.hash==='#exam'&&exam?exam.questions[exam.index]:currentQuestion()):null;world?.dispose();world=createNightWorld(canvas,{...options,question:q||options.question,motion:state.settings.motion&&!reduceMotion.matches});world?.setQuestion?.(q);if(!world){canvas.hidden=true;const fallback=document.createElement('div');fallback.className='webgl-fallback';canvas.parentElement.append(fallback);}}
function teardown(){journeyPlayer?.dispose();journeyPlayer=null;narrator.stop();questionVisual?.dispose();questionVisual=null;world?.dispose();world=null;judgeGame?.dispose();judgeGame=null;window.speechSynthesis?.cancel();}
function setNav(route){const active=['chapter','lesson','learn','garage','garage-zone'].includes(route)?'theory':['mission','result','review','drive','judge'].includes(route)?'missions':route==='exam-result'?'exam':route==='journey'?'home':route;for(const id of ['desktop-nav','mobile-nav'])$(id).innerHTML=nav.map(([r,label,i])=>`<a href="#${r}" class="${id==='desktop-nav'?'nav-item':''} ${active===r?'active':''}" ${active===r?'aria-current="page"':''} aria-label="${label}">${icon(i)}<span class="nav-label">${({home:"Hjem",missions:"Missioner",theory:"Atlas",exam:"Prøve",progress:"Fremgang"})[r]||label}</span>${id==='desktop-nav'&&r==='missions'&&dueCount()?`<span class="nav-count">${dueCount()}</span>`:''}</a>`).join('');}
function footer(){return `<p class="fine-print">NATKØRSEL er et selvstændigt øvekoncept. ${QUESTIONS.length} originale øvescenarier og ${uniqueSections} korte regelkort med myndighedskilder. Garagen uddyber ${garageSummary.topics} bilområder med delmål og opgaver til køretimen. Hele appen er endnu ikke en komplet undervisningsbog. <button class="text-link" data-action="sources">Se faglig status ↗</button></p>`;}
function heading(kicker,title,extra=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1></div>${extra}</div>`;}
function route(){teardown();const bits=location.hash.slice(1).split(':');let r=bits[0]||'home';const arg=bits[1]||'';if(r==='exam'&&exam?.result)exam=null;if(r==='exam-result'&&!exam?.result){for(const item of [...state.history].reverse()){const recovered=restoreExamResult(item,QUESTIONS,{requireSignatures:true});if(recovered){exam=recovered;break;}}}if(r==='exam-result'&&exam&&!exam.result){history.replaceState(null,'','#exam');r='exam';}setNav(r);document.body.classList.toggle('exam-active',r==='exam'&&!!exam);let content;
  switch(r){case 'home':content=renderJourneyHome(journeyViewModel(arg))+footer();break;case 'journey':content='<div id="journey-player-host"></div>'+footer();break;case 'judge':content='<div id='+String.fromCharCode(34)+'judge-host'+String.fromCharCode(34)+'>'+renderJudge()+'</div>';break;case 'pitstop':content=home();break;case 'missions':content=missions();break;case 'mission':if(!session||arg)startMission(arg);content=missionView();break;case 'review':startReview();content=missionView();break;case 'theory':content=theory();break;case 'garage':content='<div id="garage-host">'+renderGarage(arg)+'</div>'+footer();break;case 'garage-zone':content='<div id="garage-host">'+renderGarage('',arg)+'</div>'+footer();break;case 'chapter':content=chapterView(arg);break;case 'lesson':content=renderLesson(sectionMap.get(arg),LESSONS[arg])+footer();break;case 'learn':content='<div id="journey-player-host"></div>'+footer();break;case 'exam':content=exam?examView():examIntro();break;case 'progress':content=journeyProgressPage(arg);break;case 'result':content=missionResult();break;case 'exam-result':content=examResult();break;case 'drive':content=driveView();break;default:content=renderJourneyHome(journeyViewModel())+footer();}
  $('view').innerHTML=content;applySettings();bindPage(r,arg);afterRender(r);const focusTarget=r==='exam'?document.querySelector('.question-panel h2'):r==='exam-result'?document.querySelector('.result-hero h1'):$('main');if(focusTarget){focusTarget.setAttribute('tabindex','-1');focusTarget.focus({preventScroll:true});}window.scrollTo({top:0,behavior:'instant'});document.title=(r==='home'?'NATKØRSEL — din hjerne. Dit kørekort.':'NATKØRSEL — '+(nav.find(n=>n[0]===r)?.[1]||'Træning'));
}
function refreshJourneyAppearance(){if(['home','progress','journey','learn'].includes(location.hash.slice(1).split(':')[0]||'home')){const offset=window.scrollY;route();window.scrollTo({top:offset,behavior:'instant'});}}
function journeyViewModel(activeUnitId=''){
  const input={chapters:CHAPTERS,lessons:LESSONS,questions:QUESTIONS,journey:state.journey,records:state.records,now:Date.now()};
  return {units:getRouteUnits(input),daily:getDailySummary(state.journey,input.now),recommendations:getJourneyRecommendations(input),humor:state.settings.humor,activeUnitId:activeUnitId||undefined};
}
