  return renderJourneyProgress(journeyViewModel(arg))+'<div class="section-head"><h2>Dine vurderinger og prøver.</h2></div><p class="muted">'+practiced()+(practiced()===1?' regel vurderet · ':' regler vurderet · ')+mastered()+' gentaget over mindst to dage. Din tidligere fremgang er bevaret.</p>'+(state.history.length?'<div class="result-list">'+[...state.history].reverse().map(item=>'<div class="result-row"><span class="result-indicator '+(item.errors>5?'wrong':'')+'">'+item.errors+'</span><div><h3>'+item.errors+' app-fejl / 25</h3><p>'+new Date(item.at).toLocaleString('da-DK',{timeZone:'Europe/Copenhagen'})+' · '+item.unanswered+' ubesvarede</p></div></div>').join('')+'</div>':'')+footer();
