const featured=[{section:'stop',title:'STOP. IKKE SLOW.',tag:'VIGEPLIGT',description:'Et fuldt stop. En tom vej. En meget seriøs kvittering.',art:'stop',color:'var(--pink)'},{section:'sving-cykel',title:'BLINKLYS ≠ FORCE FIELD',tag:'CYKLISTER',description:'Du har blinket. Cyklisten har stadig planer.',art:'bike',color:'var(--cyan)'},{section:'ubetinget',title:'HAJTÆNDER HAR PRIORITET',tag:'KRYDS',description:'Din bil er ikke hovedpersonen i alle kryds.',art:'yield',color:'var(--acid)'}];
function featuredCards(){return featured.map((f,i)=>`<a href="#mission:${f.section}" class="mission-card" style="--card-color:${f.color}"><div class="card-top"><span>MISSION 0${i+1}</span><span class="card-tag">${f.tag}</span></div><div class="card-art art-scene">${f.art==='stop'?'<span class="stop-sign">STOP</span>':f.art==='yield'?'<strong>▽</strong>':icon(f.art)}<span class="dashed-path"></span></div><h3>${f.title}</h3><p>${f.description}</p><div class="card-bottom"><span>3 SITUATIONER + GENKALDELSE</span><span class="card-arrow">↗</span></div></a>`).join('');}
function missions(){return `${heading('DIT LÆRINGSLOOP','Korte missioner. Lange eftervirkninger.')}<div class="learning-note art-note"><div class="art-scene">${renderArt('koerelys-brain',{variant:'mission',humorOnly:true})}</div><h2>Se → vælg → forstå → husk.</h2><p>Din valgte regel, to emner fra din gentagelseskø og en genkaldelse. Du får en forklaring efter hvert svar og nye gentagelser senere. XP følger korrekte svar; der er ingen point for fart. Alle missioner er åbne.</p></div><div class="card-grid">${featuredCards()}</div><div class="section-head"><h2>Vælg, hvad din hjerne skal lære.</h2><a class="text-link" href="#review">Mine gentagelser ↗</a></div><div class="chapter-grid">${CHAPTERS.map((c,i)=>`<a href="#mission:${c.sections[0].id}" class="chapter-card" style="--card-color:${c.color}"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(c.title)}</h3><p>${esc(c.tagline)}</p><span class="mono">${c.sections.length} REGLER / ALTID ÅBEN</span></div><span class="card-arrow">↗</span></a>`).join('')}</div><div class="route-strip"><span class="art-scene art-route">${renderArt('natmobil',{variant:'mission'})}</span><div><h3>Vil du mærke vejen?</h3><p>Træn gas og bremse ved tre situationer i nattebyen.</p></div><a class="btn btn-secondary" href="#drive">Kør en tur ${icon('arrow')}</a></div>${footer()}`;}
function startMission(section){const candidates=QUESTIONS.filter(q=>q.sectionId===section),first=section==='ubetinget'?(candidates.find(q=>/hajtænd/i.test(`${q.context} ${q.prompt}`))||candidates[0]):candidates[0];const queue=chooseMission(state,QUESTIONS);const chosen=first?[first,...queue.filter(q=>q.sectionId!==first.sectionId)].slice(0,3):queue;session={questions:chosen,index:0,answers:[null,null,null,null],results:[],checked:false,phase:'learn',retry:false,xpStart:state.xp};}
